syntax:
class ClassName {
    DataType member1; // declared first
    DataType member2; // declared second
    // ...
};

// Constructor with initializer list
ClassName::ClassName() : member2(value2), member1(value1) {
    // constructor body
}

// Note: Actual memory layout follows declaration order, not initializer list order.

code_example:
class Word {
public:
    String _name; // declared first
    int _cnt;     // declared second
    Word() : _name(""), _cnt(0) {
        _name.String("0");
        _cnt = 0;
    }
};
// Memory layout: _name at lower address, _cnt at higher address, regardless of initializer list order
class X {
public:
    int a; // declared first
    int b; // declared second
    X() : b(2), a(1) {} // initializer list order differs from declaration order
};
